#include <iostream>

class GeometricObject {
public:
    virtual ~GeometricObject() = default;
    virtual double getArea() const = 0;
    virtual double getPerimeter() const = 0;
};

class Circle : public GeometricObject {
private:
    double radius;
public:
    explicit Circle(double r) : radius(r >= 0 ? r : 0) {}
    double getArea() const override { return 3.14159 * radius * radius; }
    double getPerimeter() const override { return 2 * 3.14159 * radius; }
};

class Rectangle : public GeometricObject {
private:
    double width;
    double height;
public:
    Rectangle(double w, double h)
        : width(w >= 0 ? w : 0), height(h >= 0 ? h : 0) {}
    double getArea() const override { return width * height; }
    double getPerimeter() const override { return 2 * (width + height); }
};

bool equalArea(const GeometricObject& g1, const GeometricObject& g2) {
    return g1.getArea() == g2.getArea();
}

void displayGeometricObject(const GeometricObject& g) {
    std::cout << "The area is " << g.getArea() << "\n";
    std::cout << "The perimeter is " << g.getPerimeter() << "\n";
}

int main() {
    Circle circle(5.0);
    Rectangle rectangle(5.0, 3.0);

    std::cout << "Circle info:\n";
    displayGeometricObject(circle);

    std::cout << "\nRectangle info:\n";
    displayGeometricObject(rectangle);

    std::cout << "\nThe two objects have the same area? "
              << (equalArea(circle, rectangle) ? "Yes" : "No") << "\n";

    return 0;
}

#include <iostream>

class GeometricObject {
public:
    virtual ~GeometricObject() = default;
    virtual double getArea() const = 0;
    virtual double getPerimeter() const = 0;
};

class Circle : public GeometricObject {
private:
    double radius;
public:
    explicit Circle(double r) : radius(r >= 0 ? r : 0) {}
    double getArea() const override { return 3.14159 * radius * radius; }
    double getPerimeter() const override { return 2 * 3.14159 * radius; }
    double getRadius() const { return radius; }
    double getDiameter() const { return 2 * radius; }
};

class Rectangle : public GeometricObject {
private:
    double width;
    double height;
public:
    Rectangle(double w, double h)
        : width(w >= 0 ? w : 0), height(h >= 0 ? h : 0) {}
    double getArea() const override { return width * height; }
    double getPerimeter() const override { return 2 * (width + height); }
    double getWidth() const { return width; }
    double getHeight() const { return height; }
};

void inspectAndDisplay(GeometricObject& g) {
    std::cout << "Area: " << g.getArea() << "\n";
    std::cout << "Perimeter: " << g.getPerimeter() << "\n";

    GeometricObject* p = &g;
    Circle* pCircle = dynamic_cast<Circle*>(p);
    Rectangle* pRectangle = dynamic_cast<Rectangle*>(p);

    if (pCircle != nullptr) {
        std::cout << "Circle radius: " << pCircle->getRadius() << "\n";
        std::cout << "Circle diameter: " << pCircle->getDiameter() << "\n";
    }
    if (pRectangle != nullptr) {
        std::cout << "Rectangle width: " << pRectangle->getWidth() << "\n";
        std::cout << "Rectangle height: " << pRectangle->getHeight() << "\n";
    }
}

int main() {
    Circle circle(5.0);
    Rectangle rectangle(5.0, 3.0);

    std::cout << "Circle details:\n";
    inspectAndDisplay(circle);

    std::cout << "\nRectangle details:\n";
    inspectAndDisplay(rectangle);

    return 0;
}
